window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_42", [
  {"q":"भारत में प्रथम जनगणना (1872), सांख्यिकी सर्वेक्षण और कृषि-वाणिज्य विभाग की स्थापना किस वायसराय ने की?","options":["सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)","1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण","बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना","द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त"],"correct":1,"explanation":"लॉर्ड मेयो की हत्या 1872 में अंडमान (पोर्ट ब्लेयर) यात्रा के दौरान शेर अली अफरीदी द्वारा की गई। नियमित दशकीय जनगणना 1881 में लॉर्ड रिपन के समय शुरू हुई थी।"},
  {"q":"किस अधिनियम के अंतर्गत विधान परिषद के सदस्यों को वार्षिक 'बजट' पर बहस करने व 6 दिन पूर्व सूचना पर प्रश्न पूछने का अधिकार मिला?","options":["गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार","भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष"],"correct":2,"explanation":"1892 के अधिनियम में 'निर्वाचन' शब्द नहीं था, किंतु जिला बोर्ड/विश्वविद्यालयों द्वारा परोक्ष चुनाव प्रणाली आरंभ हुई। सदस्यों को अभी अनुपूरक प्रश्न पूछने या बजट पर मतदान का अधिकार प्राप्त नहीं था।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : राम प्रसाद बिस्मिल (काकोरी कांड)\n2. करो या मरो (Do or Die) : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\n3. आराम हराम है / 'Who lives if India dies?' : स्वामी दयानंद सरस्वती\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (पटना के शायर बिस्मिल अजीमाबादी द्वारा रचित यह गजल काकोरी नायक राम प्रसाद बिस्मिल ने अमर की।) युग्म 2 सही (महात्मा गांधी ने 8 अगस्त 1942 को बंबई के ग्वालिया टैंक (अगस्त क्रांति मैदान) में 'करो या मरो' मंत्र दिया।) युग्म 3 गलत (सही: आराम हराम है / 'Who lives if India dies?' — पं. जवाहरलाल नेहरू)।"},
  {"q":"ऐतिहासिक संदर्भ में 'ऑल इंडिया स्टेट्स पीपुल्स कॉन्फ्रेंस (1927 बलवंतराय मेहता); रियासती विभाग (1947 — सरदार पटेल व सचिव वी.पी. मेनन); विलय पत्र (Instrument of Accession) व Standstill Agreement; 565 रियासतों का एकीकरण' (प्रमुख प्रक्रिया व रियासतें) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["देसी रियासतों का एकीकरण: सरदार पटेल, प्रजामंडल व ऑपरेशन पोलो","भारतीय राष्ट्रीय कांग्रेस की स्थापना (1885) एवं प्रथम चार अधिवेशन","कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885)","प्रमुख ऐतिहासिक कांग्रेस अधिवेशन (1896–1929)"],"correct":0,"explanation":"पांडिचेरी, कराकल, माहे व यनम 1954 में फ्रांस से समझौते द्वारा भारत में जुड़े, जबकि गोवा, दमन व दीव 1961 में 'ऑपरेशन विजय' द्वारा पुर्तगालियों से मुक्त हुए।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : नेताजी सुभाष चंद्र बोस\n2. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : स्वामी दयानंद सरस्वती\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (सुभाष चंद्र बोस ने आजाद हिंद फौज (INA) के पुनर्गठन के दौरान मलाया-बर्मा में यह प्रसिद्ध आह्वान किया।) युग्म 2 सही (स्वामी दयानंद सरस्वती (मूलशंकर) ने 1875 में आर्य समाज व 'सत्यार्थ प्रकाश' की रचना की।) युग्म 3 सही (बाल गंगाधर तिलक ने 1916 के लखनऊ कांग्रेस अधिवेशन और होमरूल अभियान में यह उद्घोष किया।)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. करो या मरो (Do or Die) : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\n2. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : राम प्रसाद बिस्मिल (काकोरी कांड)\n3. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : नेताजी सुभाष चंद्र बोस\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (महात्मा गांधी ने 8 अगस्त 1942 को बंबई के ग्वालिया टैंक (अगस्त क्रांति मैदान) में 'करो या मरो' मंत्र दिया।) युग्म 2 सही (पटना के शायर बिस्मिल अजीमाबादी द्वारा रचित यह गजल काकोरी नायक राम प्रसाद बिस्मिल ने अमर की।) युग्म 3 सही (सुभाष चंद्र बोस ने आजाद हिंद फौज (INA) के पुनर्गठन के दौरान मलाया-बर्मा में यह प्रसिद्ध आह्वान किया।)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लॉर्ड कॉर्नवालिस (1786-93) : बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\n2. लॉर्ड लिटन (1876-80) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\n3. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n4. लॉर्ड डलहौजी (1848-56) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'लॉर्ड लिटन (1876-80)' का सही संबंध 'वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट' से है (न कि 'द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त' से)। अकाल के समय भव्य दिल्ली दरबार (1877) तथा भारतीय भाषाई समाचार-पत्रों पर सेंसरशिप लॉर्ड लिटन की देन थी।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. करो या मरो (Do or Die) : लाला लाजपत राय (साइमन कमीशन विरोध)\n2. ब्रिटिश साम्राज्य के ताबूत में कील : राम प्रसाद बिस्मिल (काकोरी कांड)\n3. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: करो या मरो (Do or Die) — महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942))। युग्म 2 गलत (सही: ब्रिटिश साम्राज्य के ताबूत में कील — लाला लाजपत राय (साइमन कमीशन विरोध))। युग्म 3 गलत (सही: सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) — राम प्रसाद बिस्मिल (काकोरी कांड))।"},
  {"q":"भारत में 'स्थानीय स्वशासन का जनक' (1882), प्रथम कारखाना अधिनियम (1881) व इल्बर्ट बिल विवाद किसके समय हुए?","options":["स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग","द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त","सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)","बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना"],"correct":0,"explanation":"फ्लोरेंस नाइटिंगेल ने लॉर्ड रिपन को 'भारत का उद्धारक' कहा था। इल्बर्ट बिल (1883) द्वारा भारतीय न्यायाधीशों को यूरोपीयों के मुकदमे सुनने का अधिकार देने पर 'श्वेत विद्रोह' हुआ।"},
  {"q":"अखिल भारतीय किसान सभा (1936), ट्रेड यूनियन (AITUC) व वामपंथ — इसके संबंध में 'प्रमुख संगठन व नेता' कौन/क्या था?","options":["चापेकर बंधु (1897 रैंड व आयर्स्ट हत्या); मित्र मेला/अभिनव भारत (1899/1904 वी.डी. सावरकर); अनुशीलन समिति (1902 प्रमथनाथ मित्र, वारींद्र घोष, भूपेंद्र दत्त — 'युगांतर'); मुजफ्फरपुर कांड (1908 खुदीराम बोस व प्रफुल्ल चाकी); अलीपुर षड्यंत्र (अरबिंदो घोष — सी.आर. दास ने बचाया)","डॉ. बी.आर. अंबेडकर: बहिष्कृत हितकारिणी सभा (1924), 'मूकनायक' व 'बहिष्कृत भारत', महाड़ सत्याग्रह (1927), कालाराम मंदिर प्रवेश (1930), स्वतंत्र लेबर पार्टी (1936), शेड्यूल्ड कास्ट्स फेडरेशन (1942), 'एनिहिलेशन ऑफ कास्ट'; गांधीजी: 'हरिजन सेवक संघ' (1932)","हिंदुस्तान रिपब्लिकन एसोसिएशन HRA (1924 कानपुर — शचींद्र सान्याल की 'बंदी जीवन', रामप्रसाद बिस्मिल, जोगेश चटर्जी); काकोरी ट्रेन एक्शन (9 अगस्त 1925); HSRA (1928 फिरोजशाह कोटला दिल्ली — चंद्रशेखर आजाद, भगत सिंह, भगवतीचरण वोहरा 'बम का दर्शन')","बॉम्बे मिल हैंड्स एसोसिएशन (1890 एन.एम. लोखंडे); मद्रास लेबर यूनियन (1918 बी.पी. वाडिया — प्रथम आधुनिक ट्रेड यूनियन); AITUC (1920 बंबई — एन.एम. जोशी, प्रथम अध्यक्ष लाला लाजपत राय); अखिल भारतीय किसान सभा (1936 लखनऊ — सहजानंद सरस्वती अध्यक्ष, एन.जी. रंगा महासचिव)"],"correct":3,"explanation":"1928 के प्रसिद्ध बारदोली (गुजरात) किसान सत्याग्रह में बढ़ी हुई 22-30% लगान दर के विरुद्ध सफल नेतृत्व करने पर बारदोली की महिलाओं ने वल्लभभाई पटेल को 'सरदार' की उपाधि दी।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n2. लॉर्ड कॉर्नवालिस (1786-93) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\n3. वॉरेन हेस्टिंग्स (1772-85) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।) युग्म 2 गलत (सही: लॉर्ड कॉर्नवालिस (1786-93) — बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना)। युग्म 3 गलत (सही: वॉरेन हेस्टिंग्स (1772-85) — द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त)।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. आराम हराम है / 'Who lives if India dies?' : राम प्रसाद बिस्मिल (काकोरी कांड)\n2. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : लाला लाजपत राय (साइमन कमीशन विरोध)\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n4. ब्रिटिश साम्राज्य के ताबूत में कील : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: बाल गंगाधर तिलक ने 1916 के लखनऊ कांग्रेस अधिवेशन और होमरूल अभियान में यह उद्घोष किया। (अन्य सही युग्म: आराम हराम है / 'Who lives if India dies?'→पं. जवाहरलाल नेहरू, सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)→राम प्रसाद बिस्मिल (काकोरी कांड), ब्रिटिश साम्राज्य के ताबूत में कील→लाला लाजपत राय (साइमन कमीशन विरोध))।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. भारतीय परिषद अधिनियम, 1909 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n2. चार्टर अधिनियम, 1833 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n3. भारत शासन अधिनियम, 1935 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n4. भारतीय परिषद अधिनियम, 1861 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'भारत शासन अधिनियम, 1935' का सही संबंध 'अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण' से है (न कि 'भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष' से)। 321 अनुच्छेद व 10 अनुसूचियों वाले 1935 के अधिनियम ने भारतीय संविधान के संरचनात्मक भाग में सर्वाधिक योगदान दिया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लॉर्ड रिपन (1880-84) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n2. लॉर्ड कैनिंग (1856-62) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n3. लॉर्ड कॉर्नवालिस (1786-93) : बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\n4. लॉर्ड कर्जन (1899-1905) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'लॉर्ड कैनिंग (1856-62)' का सही संबंध '1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम' से है (न कि 'प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन' से)। लॉर्ड कैनिंग कंपनी के अंतिम गवर्नर-जनरल तथा 1858 के बाद भारत के प्रथम वायसराय बने।"},
  {"q":"'आराम हराम है' और 'पूर्ण स्वराज' का उद्घोष किस भारतीय राष्ट्रीय नेता से प्रमुखता से जुड़ा है?","options":["बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)","स्वामी दयानंद सरस्वती","लाला लाजपत राय (साइमन कमीशन विरोध)","पं. जवाहरलाल नेहरू"],"correct":3,"explanation":"जवाहरलाल नेहरू ने लाहौर अधिवेशन (1929) में पूर्ण स्वराज व स्वतंत्रता संग्राम में 'आराम हराम है' नारा दिया। नेहरू ने 'डिस्कवरी ऑफ इंडिया', 'ग्लिम्प्सेस ऑफ वर्ल्ड हिस्ट्री' व 'आत्मकथा' लिखी।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गवर्नर-जनरल / वायसराय एवं कार्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. लॉर्ड रिपन (1880-84)   |   1. बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\nB. लॉर्ड डलहौजी (1848-56)   |   2. स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\nC. लॉर्ड कॉर्नवालिस (1786-93)   |   3. बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\nD. लॉर्ड कर्जन (1899-1905)   |   4. व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)","options":["A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1"],"correct":0,"explanation":"सही सुमेलन: लॉर्ड रिपन (1880-84) (स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग), लॉर्ड डलहौजी (1848-56) (व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)), लॉर्ड कॉर्नवालिस (1786-93) (बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना), लॉर्ड कर्जन (1899-1905) (बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. आराम हराम है / 'Who lives if India dies?' : पं. जवाहरलाल नेहरू\n2. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n3. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : नेताजी सुभाष चंद्र बोस\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (जवाहरलाल नेहरू ने लाहौर अधिवेशन (1929) में पूर्ण स्वराज व स्वतंत्रता संग्राम में 'आराम हराम है' नारा दिया।) युग्म 2 सही (बाल गंगाधर तिलक ने 1916 के लखनऊ कांग्रेस अधिवेशन और होमरूल अभियान में यह उद्घोष किया।) युग्म 3 सही (सुभाष चंद्र बोस ने आजाद हिंद फौज (INA) के पुनर्गठन के दौरान मलाया-बर्मा में यह प्रसिद्ध आह्वान किया।)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फ्लाउड आयोग (Floud Commission) : बंगाल में स्थायी बंदोबस्त (जमींदारी) की समाप्ति की सिफारिश व बटाईदारों को 2/3 हिस्सा\n2. बटलर समिति (1927) : ब्रिटिश क्राउन व भारतीय देसी रियासतों के मध्य संबंध\n3. हंटर शिक्षा आयोग (1882) : औद्योगिक श्रमिकों एवं बागान मजदूरों की दशा व वेतन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (सर फ्रांसिस फ्लाउड आयोग ने तेभागा (बटाईदारों को उपज का 2/3 भाग) की सिफारिश की जिससे 1946 का तेभागा आंदोलन प्रेरित हुआ।) युग्म 2 सही (सर हरकोर्ट बटलर की अध्यक्षता वाली समिति ने कहा कि देसी रियासतें बिना सहमति ब्रिटिश भारतीय उत्तरदायी सरकार को न सौंपी जाएँ।) युग्म 3 गलत (सही: हंटर शिक्षा आयोग (1882) — प्राथमिक एवं माध्यमिक शिक्षा की स्थिति की जाँच)।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड लिटन (1876-80) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\n2. वॉरेन हेस्टिंग्स (1772-85) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n3. लॉर्ड रिपन (1880-84) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (अकाल के समय भव्य दिल्ली दरबार (1877) तथा भारतीय भाषाई समाचार-पत्रों पर सेंसरशिप लॉर्ड लिटन की देन थी।) युग्म 2 गलत (सही: वॉरेन हेस्टिंग्स (1772-85) — द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त)। युग्म 3 गलत (सही: लॉर्ड रिपन (1880-84) — स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n2. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n3. चार्टर अधिनियम, 1813 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (1858 के अधिनियम को शिक्षित भारतीयों ने 'अधिकारों का मैग्ना कार्टा' (महारानी विक्टोरिया घोषणा पत्र) कहा।) युग्म 2 सही (1919 के भारत शासन अधिनियम (मोंटफोर्ड सुधार) ने महिलाओं को मताधिकार व भारत हेतु उच्चायुक्त पद भी सृजित किया।) युग्म 3 सही (1813 के चार्टर एक्ट से यूरोपीय व्यापारियों व ईसाई मिशनरियों को भारत आने की अनुमति मिली।)।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भारत शासन अधिनियम, 1935 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\n2. पिट्स इंडिया एक्ट, 1784 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\n3. भारतीय परिषद अधिनियम, 1892 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n4. चार्टर अधिनियम, 1833 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: 321 अनुच्छेद व 10 अनुसूचियों वाले 1935 के अधिनियम ने भारतीय संविधान के संरचनात्मक भाग में सर्वाधिक योगदान दिया। (अन्य सही युग्म: पिट्स इंडिया एक्ट, 1784→कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण, भारतीय परिषद अधिनियम, 1892→अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार, चार्टर अधिनियम, 1833→संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति))।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n2. रेगुलेटिंग एक्ट, 1773 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n3. चार्टर अधिनियम, 1853 : केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता\n4. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)' का सही संबंध 'प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली' से है (न कि 'भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष' से)। 1919 के भारत शासन अधिनियम (मोंटफोर्ड सुधार) ने महिलाओं को मताधिकार व भारत हेतु उच्चायुक्त पद भी सृजित किया।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड लिटन (1876-80) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\n2. लॉर्ड विलियम बेंटिंक (1828-35) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\n3. चार्ल्स मेटकाफ (1835-36) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: लॉर्ड लिटन (1876-80) — वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट)। युग्म 2 गलत (सही: लॉर्ड विलियम बेंटिंक (1828-35) — सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835))। युग्म 3 गलत (सही: चार्ल्स मेटकाफ (1835-36) — 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n2. भारतीय परिषद अधिनियम, 1892 : केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता\n3. चार्टर अधिनियम, 1853 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1919 के भारत शासन अधिनियम (मोंटफोर्ड सुधार) ने महिलाओं को मताधिकार व भारत हेतु उच्चायुक्त पद भी सृजित किया।) युग्म 2 गलत (सही: भारतीय परिषद अधिनियम, 1892 — अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार)। युग्म 3 गलत (सही: चार्टर अधिनियम, 1853 — केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फ्लाउड आयोग (Floud Commission) : बंगाल में स्थायी बंदोबस्त (जमींदारी) की समाप्ति की सिफारिश व बटाईदारों को 2/3 हिस्सा\n2. हंटर शिक्षा आयोग (1882) : प्राथमिक एवं माध्यमिक शिक्षा की स्थिति की जाँच\n3. फ्रेजर आयोग (1902) : पुलिस प्रशासन व प्रांतीय CID सुधार (कर्जन)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (सर फ्रांसिस फ्लाउड आयोग ने तेभागा (बटाईदारों को उपज का 2/3 भाग) की सिफारिश की जिससे 1946 का तेभागा आंदोलन प्रेरित हुआ।) युग्म 2 सही (डब्ल्यू.डब्ल्यू. हंटर की अध्यक्षता में 1882 में प्राथमिक शिक्षा विस्तार हेतु आयोग बना (1919 की जलियाँवाला समिति भी हंटर के नाम से थी)।) युग्म 3 सही (एंड्रयू फ्रेजर की अध्यक्षता वाले आयोग की सिफारिश पर सभी प्रांतों में पुलिस व गुप्तचर (CID) विभाग बने।)।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n2. चार्ल्स मेटकाफ (1835-36) : बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\n3. लॉर्ड कॉर्नवालिस (1786-93) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।) युग्म 2 गलत (सही: चार्ल्स मेटकाफ (1835-36) — 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना)। युग्म 3 गलत (सही: लॉर्ड कॉर्नवालिस (1786-93) — बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. भारत शासन अधिनियम, 1858 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n2. चार्टर अधिनियम, 1833 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n3. भारतीय परिषद अधिनियम, 1909 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n4. भारतीय परिषद अधिनियम, 1892 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'भारत शासन अधिनियम, 1858' का सही संबंध 'कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद' से है (न कि 'भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष' से)। 1858 के अधिनियम को शिक्षित भारतीयों ने 'अधिकारों का मैग्ना कार्टा' (महारानी विक्टोरिया घोषणा पत्र) कहा।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लॉर्ड मेयो (1869-72) : 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण\n2. लॉर्ड डलहौजी (1848-56) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n3. चार्ल्स मेटकाफ (1835-36) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\n4. लॉर्ड रिपन (1880-84) : बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'लॉर्ड रिपन (1880-84)' का सही संबंध 'स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग' से है (न कि 'बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना' से)। फ्लोरेंस नाइटिंगेल ने लॉर्ड रिपन को 'भारत का उद्धारक' कहा था।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लॉर्ड डलहौजी (1848-56) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n2. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n3. लॉर्ड रिपन (1880-84) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n4. लॉर्ड मेयो (1869-72) : बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'लॉर्ड मेयो (1869-72)' का सही संबंध '1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण' से है (न कि 'बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना' से)। लॉर्ड मेयो की हत्या 1872 में अंडमान (पोर्ट ब्लेयर) यात्रा के दौरान शेर अली अफरीदी द्वारा की गई।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भारत शासन अधिनियम, 1858 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n2. चार्टर अधिनियम, 1813 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\n3. भारतीय परिषद अधिनियम, 1909 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n4. भारतीय परिषद अधिनियम, 1861 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: 1909 के मॉर्ले-मिंटो सुधार ने फूट डालो और राज करो की नीति को संवैधानिक रूप दिया (मिंटो को साम्प्रदायिक निर्वाचन का जनक कहा गया)। (अन्य सही युग्म: भारत शासन अधिनियम, 1858→कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद, चार्टर अधिनियम, 1813→भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष, भारतीय परिषद अधिनियम, 1861→मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह))।"},
  {"q":"[PSC/CDS युग्म पहचान — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लॉर्ड मेयो (1869-72) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n2. लॉर्ड डलहौजी (1848-56) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n3. लॉर्ड लिनलिथगो (1936-44) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\n4. लॉर्ड कैनिंग (1856-62) : 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: लॉर्ड कैनिंग कंपनी के अंतिम गवर्नर-जनरल तथा 1858 के बाद भारत के प्रथम वायसराय बने। (अन्य सही युग्म: लॉर्ड मेयो (1869-72)→1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण, लॉर्ड डलहौजी (1848-56)→व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854), लॉर्ड लिनलिथगो (1936-44)→प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन)।"},
  {"q":"किस अधिनियम ने पहली बार विधायिका में भारतीय गैर-सरकारी सदस्यों का मनोनयन (बनारस राजा, पटियाला महाराजा व दिनकर राव) और अध्यादेश शक्ति दी?","options":["कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)","गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष"],"correct":1,"explanation":"1861 के भारतीय परिषद अधिनियम ने कानून निर्माण प्रक्रिया में भारतीय प्रतिनिधियों को शामिल करने की शुरुआत की। लॉर्ड कैनिंग द्वारा 1859 में शुरू की गई पोर्टफोलियो (विभागीय) प्रणाली को इस एक्ट ने वैधानिक मान्यता दी।"},
  {"q":"किस अधिनियम को 'मॉर्ले-मिंटो सुधार' कहा जाता है जिसने भारत में साम्प्रदायिक पृथक निर्वाचक मंडल प्रारंभ किया?","options":["कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य","भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष","गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ"],"correct":1,"explanation":"1909 के मॉर्ले-मिंटो सुधार ने फूट डालो और राज करो की नीति को संवैधानिक रूप दिया (मिंटो को साम्प्रदायिक निर्वाचन का जनक कहा गया)। गांधीजी ने कहा था कि इस एक्ट ने हमारा सर्वनाश कर दिया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. करो या मरो (Do or Die) : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\n2. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n3. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : लाला लाजपत राय (साइमन कमीशन विरोध)\n4. आराम हराम है / 'Who lives if India dies?' : पं. जवाहरलाल नेहरू","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)' का सही संबंध 'राम प्रसाद बिस्मिल (काकोरी कांड)' से है (न कि 'लाला लाजपत राय (साइमन कमीशन विरोध)' से)। पटना के शायर बिस्मिल अजीमाबादी द्वारा रचित यह गजल काकोरी नायक राम प्रसाद बिस्मिल ने अमर की।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गवर्नर-जनरल / वायसराय एवं कार्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. लॉर्ड लिनलिथगो (1936-44)   |   1. 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\nB. लॉर्ड कर्जन (1899-1905)   |   2. प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\nC. चार्ल्स मेटकाफ (1835-36)   |   3. स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\nD. लॉर्ड रिपन (1880-84)   |   4. बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन","options":["A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3"],"correct":1,"explanation":"सही सुमेलन: लॉर्ड लिनलिथगो (1936-44) (प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन), लॉर्ड कर्जन (1899-1905) (बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन), चार्ल्स मेटकाफ (1835-36) (1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना), लॉर्ड रिपन (1880-84) (स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग)।"},
  {"q":"देसी रियासतों का एकीकरण: सरदार पटेल, प्रजामंडल व ऑपरेशन पोलो — इसके संबंध में 'प्रमुख प्रक्रिया व रियासतें' कौन/क्या था?","options":["28 दिसंबर 1885 गोकुलदास तेजपाल संस्कृत कॉलेज, बंबई (72 प्रतिनिधि, ए.ओ. ह्यूम द्वारा पहल, वायसराय डफरिन); 1885 बंबई (व्योमेश चंद्र बनर्जी); 1886 कलकत्ता (दादाभाई नौरोजी); 1887 मद्रास (बदरुद्दीन तैयबजी — प्रथम मुस्लिम अध्यक्ष); 1888 इलाहाबाद (जॉर्ज यूल — प्रथम अंग्रेज अध्यक्ष)","बंगभाषा प्रकाशिका सभा (1836), लैंडहोल्डर्स सोसाइटी (1838 द्वारकानाथ टैगोर — प्रथम राजनीतिक संगठन), ईस्ट इंडिया एसोसिएशन (1866 लंदन, दादाभाई नौरोजी), पूना सार्वजनिक सभा (1870 एम.जी. रानाडे व जी.वी. जोशी), इंडियन एसोसिएशन (1876 सुरेंद्रनाथ बनर्जी व आनंद मोहन बोस)","1896 कलकत्ता (रहीमतुल्ला सयानी — पहली बार 'वंदे मातरम'); 1905 बनारस (गोखले — स्वदेशी समर्थन); 1906 कलकत्ता (नौरोजी — 'स्वराज' लक्ष्य); 1911 कलकत्ता (बिशन नारायण धर — 'जन गण मन'); 1916 लखनऊ (अंबिका चरण मजूमदार — नरम-गरम व कांग्रेस-लीग समझौता)","ऑल इंडिया स्टेट्स पीपुल्स कॉन्फ्रेंस (1927 बलवंतराय मेहता); रियासती विभाग (1947 — सरदार पटेल व सचिव वी.पी. मेनन); विलय पत्र (Instrument of Accession) व Standstill Agreement; 565 रियासतों का एकीकरण"],"correct":3,"explanation":"पांडिचेरी, कराकल, माहे व यनम 1954 में फ्रांस से समझौते द्वारा भारत में जुड़े, जबकि गोवा, दमन व दीव 1961 में 'ऑपरेशन विजय' द्वारा पुर्तगालियों से मुक्त हुए।"},
  {"q":"'सरफरोशी की तमन्ना अब हमारे दिल में है' गीत (मूल रचना: बिस्मिल अजीमाबादी) को किस क्रांतिकारी ने अमर कर दिया?","options":["पं. जवाहरलाल नेहरू","राम प्रसाद बिस्मिल (काकोरी कांड)","स्वामी दयानंद सरस्वती","बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)"],"correct":1,"explanation":"पटना के शायर बिस्मिल अजीमाबादी द्वारा रचित यह गजल काकोरी नायक राम प्रसाद बिस्मिल ने अमर की। गोरखपुर जेल में फाँसी से पहले उन्होंने 'अब तो काम पूरा हो गया' कहकर दूध लेने से इनकार किया था।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : नेताजी सुभाष चंद्र बोस\n2. करो या मरो (Do or Die) : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (सुभाष चंद्र बोस ने आजाद हिंद फौज (INA) के पुनर्गठन के दौरान मलाया-बर्मा में यह प्रसिद्ध आह्वान किया।) युग्म 2 सही (महात्मा गांधी ने 8 अगस्त 1942 को बंबई के ग्वालिया टैंक (अगस्त क्रांति मैदान) में 'करो या मरो' मंत्र दिया।) युग्म 3 सही (बाल गंगाधर तिलक ने 1916 के लखनऊ कांग्रेस अधिवेशन और होमरूल अभियान में यह उद्घोष किया।)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. करो या मरो (Do or Die)   |   1. राम प्रसाद बिस्मिल (काकोरी कांड)\nB. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)   |   2. नेताजी सुभाष चंद्र बोस\nC. स्वराज मेरा जन्मसिद्ध अधिकार है   |   3. महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\nD. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा   |   4. बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: करो या मरो (Do or Die) (महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)), सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) (राम प्रसाद बिस्मिल (काकोरी कांड)), स्वराज मेरा जन्मसिद्ध अधिकार है (बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)), तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा (नेताजी सुभाष चंद्र बोस)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n2. चार्टर अधिनियम, 1813 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n3. भारत शासन अधिनियम, 1935 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (1919 के भारत शासन अधिनियम (मोंटफोर्ड सुधार) ने महिलाओं को मताधिकार व भारत हेतु उच्चायुक्त पद भी सृजित किया।) युग्म 2 सही (1813 के चार्टर एक्ट से यूरोपीय व्यापारियों व ईसाई मिशनरियों को भारत आने की अनुमति मिली।) युग्म 3 गलत (सही: भारत शासन अधिनियम, 1935 — अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. आराम हराम है / 'Who lives if India dies?' : पं. जवाहरलाल नेहरू\n2. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : राम प्रसाद बिस्मिल (काकोरी कांड)\n3. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : स्वामी दयानंद सरस्वती\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (जवाहरलाल नेहरू ने लाहौर अधिवेशन (1929) में पूर्ण स्वराज व स्वतंत्रता संग्राम में 'आराम हराम है' नारा दिया।) युग्म 2 गलत (सही: तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा — नेताजी सुभाष चंद्र बोस)। युग्म 3 गलत (सही: सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) — राम प्रसाद बिस्मिल (काकोरी कांड))।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. ब्रिटिश साम्राज्य के ताबूत में कील : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n2. स्वराज मेरा जन्मसिद्ध अधिकार है : पं. जवाहरलाल नेहरू\n3. आराम हराम है / 'Who lives if India dies?' : नेताजी सुभाष चंद्र बोस\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: ब्रिटिश साम्राज्य के ताबूत में कील — लाला लाजपत राय (साइमन कमीशन विरोध))। युग्म 2 गलत (सही: स्वराज मेरा जन्मसिद्ध अधिकार है — बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916))। युग्म 3 गलत (सही: आराम हराम है / 'Who lives if India dies?' — पं. जवाहरलाल नेहरू)।"},
  {"q":"किस अधिनियम द्वारा प्रांतों में 'द्वैध शासन' (आरक्षित एवं हस्तांतरित विषय) तथा केंद्र में द्विसदनात्मक विधायिका लागू हुई?","options":["गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली","भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष"],"correct":2,"explanation":"1919 के भारत शासन अधिनियम (मोंटफोर्ड सुधार) ने महिलाओं को मताधिकार व भारत हेतु उच्चायुक्त पद भी सृजित किया। प्रांतीय द्वैध शासन की जांच हेतु 1924 में 'मुड्डीमैन समिति' गठित हुई थी।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. भारतीय परिषद अधिनियम, 1892 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\n2. भारतीय परिषद अधिनियम, 1909 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n3. भारतीय परिषद अधिनियम, 1861 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n4. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'भारतीय परिषद अधिनियम, 1861' का सही संबंध 'मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)' से है (न कि 'गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ' से)। 1861 के भारतीय परिषद अधिनियम ने कानून निर्माण प्रक्रिया में भारतीय प्रतिनिधियों को शामिल करने की शुरुआत की।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड कैनिंग (1856-62) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\n2. वॉरेन हेस्टिंग्स (1772-85) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\n3. चार्ल्स मेटकाफ (1835-36) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: लॉर्ड कैनिंग (1856-62) — 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम)। युग्म 2 गलत (सही: वॉरेन हेस्टिंग्स (1772-85) — द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त)। युग्म 3 गलत (सही: चार्ल्स मेटकाफ (1835-36) — 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना)।"},
  {"q":"'दिल्ली चलो' तथा 'तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा' किस क्रांतिकारी महानायक के नारे थे?","options":["पं. जवाहरलाल नेहरू","नेताजी सुभाष चंद्र बोस","बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)","स्वामी दयानंद सरस्वती"],"correct":1,"explanation":"सुभाष चंद्र बोस ने आजाद हिंद फौज (INA) के पुनर्गठन के दौरान मलाया-बर्मा में यह प्रसिद्ध आह्वान किया। उन्होंने 6 जुलाई 1944 को रंगून रेडियो से महात्मा गांधी को प्रथम बार 'राष्ट्रपिता' कहकर संबोधित किया।"},
  {"q":"1878 का 'वर्नाक्युलर प्रेस एक्ट', भारतीय शस्त्र अधिनियम व 1877 का प्रथम दिल्ली दरबार किस प्रतिक्रियावादी वायसराय ने लागू किया?","options":["वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट","बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना","सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)","द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त"],"correct":0,"explanation":"अकाल के समय भव्य दिल्ली दरबार (1877) तथा भारतीय भाषाई समाचार-पत्रों पर सेंसरशिप लॉर्ड लिटन की देन थी। लिटन साहित्य जगत में 'ओवन मेरेडिथ' उपनाम से भी लिखते थे।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. आराम हराम है / 'Who lives if India dies?' : राम प्रसाद बिस्मिल (काकोरी कांड)\n2. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : लाला लाजपत राय (साइमन कमीशन विरोध)\n4. करो या मरो (Do or Die) : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: महात्मा गांधी ने 8 अगस्त 1942 को बंबई के ग्वालिया टैंक (अगस्त क्रांति मैदान) में 'करो या मरो' मंत्र दिया। (अन्य सही युग्म: आराम हराम है / 'Who lives if India dies?'→पं. जवाहरलाल नेहरू, सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)→राम प्रसाद बिस्मिल (काकोरी कांड), स्वराज मेरा जन्मसिद्ध अधिकार है→बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916))।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1935 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n2. चार्टर अधिनियम, 1813 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n3. भारत शासन अधिनियम, 1858 : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: भारत शासन अधिनियम, 1935 — अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण)। युग्म 2 गलत (सही: चार्टर अधिनियम, 1813 — भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष)। युग्म 3 गलत (सही: भारत शासन अधिनियम, 1858 — कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद)।"},
  {"q":"'मेरे शरीर पर पड़ी एक-एक लाठी ब्रिटिश साम्राज्य के ताबूत में कील साबित होगी' — यह कथन 1928 में किसका था?","options":["पं. जवाहरलाल नेहरू","लाला लाजपत राय (साइमन कमीशन विरोध)","स्वामी दयानंद सरस्वती","बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)"],"correct":1,"explanation":"लाहौर में 30 अक्टूबर 1928 को साइमन विरोधी जुलूस में पुलिस लाठीचार्ज में घायल लाला लाजपत राय ने यह कथन कहा। सॉन्डर्स की हत्या कर भगत सिंह-राजगुरु-आजाद ने इस प्रहार का बदला लिया।"},
  {"q":"[PSC/CDS युग्म पहचान — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लॉर्ड डलहौजी (1848-56) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\n2. लॉर्ड विलियम बेंटिंक (1828-35) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\n3. लॉर्ड रिपन (1880-84) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n4. चार्ल्स मेटकाफ (1835-36) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: फ्लोरेंस नाइटिंगेल ने लॉर्ड रिपन को 'भारत का उद्धारक' कहा था। (अन्य सही युग्म: लॉर्ड डलहौजी (1848-56)→व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854), लॉर्ड विलियम बेंटिंक (1828-35)→सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835), चार्ल्स मेटकाफ (1835-36)→1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. भारतीय परिषद अधिनियम, 1892 : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n2. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n3. भारतीय परिषद अधिनियम, 1861 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\n4. भारतीय परिषद अधिनियम, 1909 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'भारतीय परिषद अधिनियम, 1892' का सही संबंध 'अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार' से है (न कि 'प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली' से)। 1892 के अधिनियम में 'निर्वाचन' शब्द नहीं था, किंतु जिला बोर्ड/विश्वविद्यालयों द्वारा परोक्ष चुनाव प्रणाली आरंभ हुई।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : नेताजी सुभाष चंद्र बोस\n2. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : स्वामी दयानंद सरस्वती\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\n4. ब्रिटिश साम्राज्य के ताबूत में कील : लाला लाजपत राय (साइमन कमीशन विरोध)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'स्वराज मेरा जन्मसिद्ध अधिकार है' का सही संबंध 'बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)' से है (न कि 'महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)' से)। बाल गंगाधर तिलक ने 1916 के लखनऊ कांग्रेस अधिवेशन और होमरूल अभियान में यह उद्घोष किया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लॉर्ड रिपन (1880-84) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n2. लॉर्ड विलियम बेंटिंक (1828-35) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\n3. लॉर्ड लिटन (1876-80) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\n4. लॉर्ड लिनलिथगो (1936-44) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'लॉर्ड लिनलिथगो (1936-44)' का सही संबंध 'प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन' से है (न कि 'द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त' से)। लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. पिट्स इंडिया एक्ट, 1784 : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n2. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n3. भारतीय परिषद अधिनियम, 1909 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n4. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: 1858 के अधिनियम को शिक्षित भारतीयों ने 'अधिकारों का मैग्ना कार्टा' (महारानी विक्टोरिया घोषणा पत्र) कहा। (अन्य सही युग्म: पिट्स इंडिया एक्ट, 1784→कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण, भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)→प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली, भारतीय परिषद अधिनियम, 1909→मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. करो या मरो (Do or Die) : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n2. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : स्वामी दयानंद सरस्वती\n3. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : राम प्रसाद बिस्मिल (काकोरी कांड)\n4. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : नेताजी सुभाष चंद्र बोस","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'करो या मरो (Do or Die)' का सही संबंध 'महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)' से है (न कि 'बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)' से)। महात्मा गांधी ने 8 अगस्त 1942 को बंबई के ग्वालिया टैंक (अगस्त क्रांति मैदान) में 'करो या मरो' मंत्र दिया।"},
  {"q":"1857 के विद्रोह के बाद भारत के प्रथम वायसराय तथा 1861 में 'पोर्टफोलियो प्रणाली' शुरू करने वाले शासक कौन थे?","options":["सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)","1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम","द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त","बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना"],"correct":1,"explanation":"लॉर्ड कैनिंग कंपनी के अंतिम गवर्नर-जनरल तथा 1858 के बाद भारत के प्रथम वायसराय बने। इन्हीं के समय 1860 में जेम्स विल्सन ने भारत में प्रथम बजट व आयकर प्रस्तुत किया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)   |   1. भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\nB. रेगुलेटिंग एक्ट, 1773   |   2. संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\nC. चार्टर अधिनियम, 1833   |   3. प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\nD. चार्टर अधिनियम, 1813   |   4. गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","options":["A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1"],"correct":1,"explanation":"सही सुमेलन: भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) (प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली), रेगुलेटिंग एक्ट, 1773 (गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ), चार्टर अधिनियम, 1833 (संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)), चार्टर अधिनियम, 1813 (भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष)।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. स्वराज मेरा जन्मसिद्ध अधिकार है : लाला लाजपत राय (साइमन कमीशन विरोध)\n2. ब्रिटिश साम्राज्य के ताबूत में कील : पं. जवाहरलाल नेहरू\n3. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : नेताजी सुभाष चंद्र बोस\n4. आराम हराम है / 'Who lives if India dies?' : राम प्रसाद बिस्मिल (काकोरी कांड)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: सुभाष चंद्र बोस ने आजाद हिंद फौज (INA) के पुनर्गठन के दौरान मलाया-बर्मा में यह प्रसिद्ध आह्वान किया। (अन्य सही युग्म: स्वराज मेरा जन्मसिद्ध अधिकार है→बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916), ब्रिटिश साम्राज्य के ताबूत में कील→लाला लाजपत राय (साइमन कमीशन विरोध), आराम हराम है / 'Who lives if India dies?'→पं. जवाहरलाल नेहरू)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा   |   1. बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\nB. करो या मरो (Do or Die)   |   2. नेताजी सुभाष चंद्र बोस\nC. स्वराज मेरा जन्मसिद्ध अधिकार है   |   3. राम प्रसाद बिस्मिल (काकोरी कांड)\nD. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)   |   4. महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"correct":0,"explanation":"सही सुमेलन: तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा (नेताजी सुभाष चंद्र बोस), करो या मरो (Do or Die) (महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)), स्वराज मेरा जन्मसिद्ध अधिकार है (बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)), सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) (राम प्रसाद बिस्मिल (काकोरी कांड))।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n2. लॉर्ड विलियम बेंटिंक (1828-35) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\n3. वॉरेन हेस्टिंग्स (1772-85) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।) युग्म 2 सही (राजाराम मोहन राय के सहयोग से लॉर्ड विलियम बेंटिंक ने 1829 में सती प्रथा अवैध घोषित की।) युग्म 3 सही (वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल (1773 एक्ट) बने; उन्होंने कलकत्ता मदरसा (1781) की स्थापना भी की।)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : लाला लाजपत राय (साइमन कमीशन विरोध)\n2. ब्रिटिश साम्राज्य के ताबूत में कील : राम प्रसाद बिस्मिल (काकोरी कांड)\n3. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : पं. जवाहरलाल नेहरू\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग — स्वामी दयानंद सरस्वती)। युग्म 2 गलत (सही: ब्रिटिश साम्राज्य के ताबूत में कील — लाला लाजपत राय (साइमन कमीशन विरोध))। युग्म 3 गलत (सही: सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) — राम प्रसाद बिस्मिल (काकोरी कांड))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. करो या मरो (Do or Die)   |   1. पं. जवाहरलाल नेहरू\nB. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग   |   2. नेताजी सुभाष चंद्र बोस\nC. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा   |   3. महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\nD. आराम हराम है / 'Who lives if India dies?'   |   4. स्वामी दयानंद सरस्वती","options":["A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1"],"correct":1,"explanation":"सही सुमेलन: करो या मरो (Do or Die) (महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)), वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग (स्वामी दयानंद सरस्वती), तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा (नेताजी सुभाष चंद्र बोस), आराम हराम है / 'Who lives if India dies?' (पं. जवाहरलाल नेहरू)।"},
  {"q":"ऐतिहासिक संदर्भ में 'बॉम्बे मिल हैंड्स एसोसिएशन (1890 एन.एम. लोखंडे); मद्रास लेबर यूनियन (1918 बी.पी. वाडिया — प्रथम आधुनिक ट्रेड यूनियन); AITUC (1920 बंबई — एन.एम. जोशी, प्रथम अध्यक्ष लाला लाजपत राय); अखिल भारतीय किसान सभा (1936 लखनऊ — सहजानंद सरस्वती अध्यक्ष, एन.जी. रंगा महासचिव)' (प्रमुख संगठन व नेता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["अखिल भारतीय किसान सभा (1936), ट्रेड यूनियन (AITUC) व वामपंथ","भारतीय राष्ट्रीय कांग्रेस की स्थापना (1885) एवं प्रथम चार अधिवेशन","कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885)","प्रमुख ऐतिहासिक कांग्रेस अधिवेशन (1896–1929)"],"correct":0,"explanation":"1928 के प्रसिद्ध बारदोली (गुजरात) किसान सत्याग्रह में बढ़ी हुई 22-30% लगान दर के विरुद्ध सफल नेतृत्व करने पर बारदोली की महिलाओं ने वल्लभभाई पटेल को 'सरदार' की उपाधि दी।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. आराम हराम है / 'Who lives if India dies?' : राम प्रसाद बिस्मिल (काकोरी कांड)\n2. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : लाला लाजपत राय (साइमन कमीशन विरोध)\n4. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : स्वामी दयानंद सरस्वती","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: स्वामी दयानंद सरस्वती (मूलशंकर) ने 1875 में आर्य समाज व 'सत्यार्थ प्रकाश' की रचना की। (अन्य सही युग्म: आराम हराम है / 'Who lives if India dies?'→पं. जवाहरलाल नेहरू, सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)→राम प्रसाद बिस्मिल (काकोरी कांड), स्वराज मेरा जन्मसिद्ध अधिकार है→बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916))।"},
  {"q":"'अखिल भारतीय किसान सभा (1936), ट्रेड यूनियन (AITUC) व वामपंथ' के ऐतिहासिक संदर्भ में 'वामपंथी दल व षड्यंत्र' निम्नलिखित में से क्या है?","options":["सेफ्टी वॉल्व सिद्धांत (लाला लाजपत राय ने 'यंग इंडिया' में चर्चा की); आधुनिक मत: 'तड़ित चालक' (Lightning Conductor — गोखले ने ह्यूम का उपयोग किया)","1924 बेलगाम (महात्मा गांधी — एकमात्र अध्यक्षता); 1929 लाहौर (जवाहरलाल नेहरू — 'पूर्ण स्वराज' प्रस्ताव, 26 जनवरी 1930 प्रथम स्वतंत्रता दिवस)","सीपीआई की ताशकंद में स्थापना (1920 एम.एन. रॉय); भारत में कानपुर सम्मेलन (1925 सत्यभक्त); मेरठ षड्यंत्र केस (1929-33); कांग्रेस सोशलिस्ट पार्टी (1934 पटना — आचार्य नरेंद्र देव, जे.पी. नारायण)","मद्रास महाजन सभा (1884 — वी. राघवाचारी, जी. सुब्रमण्यम अय्यर, पी. आनंद चारलु); बॉम्बे प्रेसीडेंसी एसोसिएशन (1885 — फिरोजशाह मेहता, के.टी. तैलंग, बदरुद्दीन तैयबजी)"],"correct":2,"explanation":"1928 के प्रसिद्ध बारदोली (गुजरात) किसान सत्याग्रह में बढ़ी हुई 22-30% लगान दर के विरुद्ध सफल नेतृत्व करने पर बारदोली की महिलाओं ने वल्लभभाई पटेल को 'सरदार' की उपाधि दी।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. ह्विटले आयोग (Whitley, 1929) : औद्योगिक श्रमिकों एवं बागान मजदूरों की दशा व वेतन\n2. हंटर शिक्षा आयोग (1882) : प्राथमिक एवं माध्यमिक शिक्षा की स्थिति की जाँच\n3. ली आयोग (Lee Commission, 1923) : अखिल भारतीय सिविल सेवा में भारतीय व ब्रिटिश 50-50 अनुपात\n4. फ्लाउड आयोग (Floud Commission) : पुलिस प्रशासन व प्रांतीय CID सुधार (कर्जन)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'फ्लाउड आयोग (Floud Commission)' का सही संबंध 'बंगाल में स्थायी बंदोबस्त (जमींदारी) की समाप्ति की सिफारिश व बटाईदारों को 2/3 हिस्सा' से है (न कि 'पुलिस प्रशासन व प्रांतीय CID सुधार (कर्जन)' से)। सर फ्रांसिस फ्लाउड आयोग ने तेभागा (बटाईदारों को उपज का 2/3 भाग) की सिफारिश की जिससे 1946 का तेभागा आंदोलन प्रेरित हुआ।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. ब्रिटिश साम्राज्य के ताबूत में कील : लाला लाजपत राय (साइमन कमीशन विरोध)\n2. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : नेताजी सुभाष चंद्र बोस\n3. आराम हराम है / 'Who lives if India dies?' : राम प्रसाद बिस्मिल (काकोरी कांड)\n4. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'आराम हराम है / 'Who lives if India dies?'' का सही संबंध 'पं. जवाहरलाल नेहरू' से है (न कि 'राम प्रसाद बिस्मिल (काकोरी कांड)' से)। जवाहरलाल नेहरू ने लाहौर अधिवेशन (1929) में पूर्ण स्वराज व स्वतंत्रता संग्राम में 'आराम हराम है' नारा दिया।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : राम प्रसाद बिस्मिल (काकोरी कांड)\n2. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\n3. करो या मरो (Do or Die) : पं. जवाहरलाल नेहरू\n4. आराम हराम है / 'Who lives if India dies?' : लाला लाजपत राय (साइमन कमीशन विरोध)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: पटना के शायर बिस्मिल अजीमाबादी द्वारा रचित यह गजल काकोरी नायक राम प्रसाद बिस्मिल ने अमर की। (अन्य सही युग्म: तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा→नेताजी सुभाष चंद्र बोस, करो या मरो (Do or Die)→महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942), आराम हराम है / 'Who lives if India dies?'→पं. जवाहरलाल नेहरू)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. ब्रिटिश साम्राज्य के ताबूत में कील : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n2. आराम हराम है / 'Who lives if India dies?' : पं. जवाहरलाल नेहरू\n3. करो या मरो (Do or Die) : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\n4. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : स्वामी दयानंद सरस्वती","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'ब्रिटिश साम्राज्य के ताबूत में कील' का सही संबंध 'लाला लाजपत राय (साइमन कमीशन विरोध)' से है (न कि 'बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)' से)। लाहौर में 30 अक्टूबर 1928 को साइमन विरोधी जुलूस में पुलिस लाठीचार्ज में घायल लाला लाजपत राय ने यह कथन कहा।"},
  {"q":"जमींदारी प्रथा की समीक्षा के लिए 1938-40 में बंगाल सरकार ने कौन-सा प्रसिद्ध आयोग बनाया था?","options":["पुलिस प्रशासन व प्रांतीय CID सुधार (कर्जन)","बंगाल में स्थायी बंदोबस्त (जमींदारी) की समाप्ति की सिफारिश व बटाईदारों को 2/3 हिस्सा","औद्योगिक श्रमिकों एवं बागान मजदूरों की दशा व वेतन","प्राथमिक एवं माध्यमिक शिक्षा की स्थिति की जाँच"],"correct":1,"explanation":"सर फ्रांसिस फ्लाउड आयोग ने तेभागा (बटाईदारों को उपज का 2/3 भाग) की सिफारिश की जिससे 1946 का तेभागा आंदोलन प्रेरित हुआ। यह बंगाल के किसान इतिहास की अत्यंत महत्वपूर्ण रिपोर्ट मानी जाती है।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. ब्रिटिश साम्राज्य के ताबूत में कील : लाला लाजपत राय (साइमन कमीशन विरोध)\n2. आराम हराम है / 'Who lives if India dies?' : पं. जवाहरलाल नेहरू\n3. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : स्वामी दयानंद सरस्वती\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (लाहौर में 30 अक्टूबर 1928 को साइमन विरोधी जुलूस में पुलिस लाठीचार्ज में घायल लाला लाजपत राय ने यह कथन कहा।) युग्म 2 सही (जवाहरलाल नेहरू ने लाहौर अधिवेशन (1929) में पूर्ण स्वराज व स्वतंत्रता संग्राम में 'आराम हराम है' नारा दिया।) युग्म 3 गलत (सही: सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) — राम प्रसाद बिस्मिल (काकोरी कांड))।"},
  {"q":"[PSC/CDS युग्म पहचान — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लॉर्ड मेयो (1869-72) : 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण\n2. लॉर्ड कर्जन (1899-1905) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\n3. चार्ल्स मेटकाफ (1835-36) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\n4. लॉर्ड लिटन (1876-80) : 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: लॉर्ड मेयो की हत्या 1872 में अंडमान (पोर्ट ब्लेयर) यात्रा के दौरान शेर अली अफरीदी द्वारा की गई। (अन्य सही युग्म: लॉर्ड कर्जन (1899-1905)→बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन, चार्ल्स मेटकाफ (1835-36)→1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना, लॉर्ड लिटन (1876-80)→वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गवर्नर-जनरल / वायसराय एवं कार्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. लॉर्ड कैनिंग (1856-62)   |   1. 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण\nB. लॉर्ड डलहौजी (1848-56)   |   2. बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\nC. लॉर्ड कॉर्नवालिस (1786-93)   |   3. 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम\nD. लॉर्ड मेयो (1869-72)   |   4. व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)","options":["A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: लॉर्ड कैनिंग (1856-62) (1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम), लॉर्ड डलहौजी (1848-56) (व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)), लॉर्ड कॉर्नवालिस (1786-93) (बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना), लॉर्ड मेयो (1869-72) (1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1935 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\n2. रेगुलेटिंग एक्ट, 1773 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n3. भारतीय परिषद अधिनियम, 1892 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (321 अनुच्छेद व 10 अनुसूचियों वाले 1935 के अधिनियम ने भारतीय संविधान के संरचनात्मक भाग में सर्वाधिक योगदान दिया।) युग्म 2 सही (1773 के रेगुलेटिंग एक्ट से वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल बने व बंबई-मद्रास उनके अधीन हुए।) युग्म 3 गलत (सही: भारतीय परिषद अधिनियम, 1892 — अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. ली आयोग (Lee Commission, 1923) : पुलिस प्रशासन व प्रांतीय CID सुधार (कर्जन)\n2. फ्रेजर आयोग (1902) : ब्रिटिश क्राउन व भारतीय देसी रियासतों के मध्य संबंध\n3. बटलर समिति (1927) : प्राथमिक एवं माध्यमिक शिक्षा की स्थिति की जाँच\n4. फ्लाउड आयोग (Floud Commission) : बंगाल में स्थायी बंदोबस्त (जमींदारी) की समाप्ति की सिफारिश व बटाईदारों को 2/3 हिस्सा","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: सर फ्रांसिस फ्लाउड आयोग ने तेभागा (बटाईदारों को उपज का 2/3 भाग) की सिफारिश की जिससे 1946 का तेभागा आंदोलन प्रेरित हुआ। (अन्य सही युग्म: ली आयोग (Lee Commission, 1923)→अखिल भारतीय सिविल सेवा में भारतीय व ब्रिटिश 50-50 अनुपात, फ्रेजर आयोग (1902)→पुलिस प्रशासन व प्रांतीय CID सुधार (कर्जन), बटलर समिति (1927)→ब्रिटिश क्राउन व भारतीय देसी रियासतों के मध्य संबंध)।"},
  {"q":"[PSC/CDS युग्म पहचान — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n2. वॉरेन हेस्टिंग्स (1772-85) : 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण\n3. लॉर्ड मेयो (1869-72) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\n4. लॉर्ड लिटन (1876-80) : 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे। (अन्य सही युग्म: वॉरेन हेस्टिंग्स (1772-85)→द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त, लॉर्ड मेयो (1869-72)→1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण, लॉर्ड लिटन (1876-80)→वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. आराम हराम है / 'Who lives if India dies?' : पं. जवाहरलाल नेहरू\n2. ब्रिटिश साम्राज्य के ताबूत में कील : लाला लाजपत राय (साइमन कमीशन विरोध)\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : नेताजी सुभाष चंद्र बोस\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (जवाहरलाल नेहरू ने लाहौर अधिवेशन (1929) में पूर्ण स्वराज व स्वतंत्रता संग्राम में 'आराम हराम है' नारा दिया।) युग्म 2 सही (लाहौर में 30 अक्टूबर 1928 को साइमन विरोधी जुलूस में पुलिस लाठीचार्ज में घायल लाला लाजपत राय ने यह कथन कहा।) युग्म 3 गलत (सही: स्वराज मेरा जन्मसिद्ध अधिकार है — बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. भारतीय परिषद अधिनियम, 1892   |   1. प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\nB. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)   |   2. भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\nC. भारतीय परिषद अधिनियम, 1861   |   3. अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\nD. चार्टर अधिनियम, 1813   |   4. मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)","options":["A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"correct":2,"explanation":"सही सुमेलन: भारतीय परिषद अधिनियम, 1892 (अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार), भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) (प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली), भारतीय परिषद अधिनियम, 1861 (मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)), चार्टर अधिनियम, 1813 (भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n2. चार्टर अधिनियम, 1853 : केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता\n3. भारतीय परिषद अधिनियम, 1909 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n4. पिट्स इंडिया एक्ट, 1784 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'भारतीय परिषद अधिनियम, 1909' का सही संबंध 'मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य' से है (न कि 'गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ' से)। 1909 के मॉर्ले-मिंटो सुधार ने फूट डालो और राज करो की नीति को संवैधानिक रूप दिया (मिंटो को साम्प्रदायिक निर्वाचन का जनक कहा गया)।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड रिपन (1880-84) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n2. लॉर्ड कर्जन (1899-1905) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\n3. लॉर्ड कैनिंग (1856-62) : 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (फ्लोरेंस नाइटिंगेल ने लॉर्ड रिपन को 'भारत का उद्धारक' कहा था।) युग्म 2 सही (लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।) युग्म 3 सही (लॉर्ड कैनिंग कंपनी के अंतिम गवर्नर-जनरल तथा 1858 के बाद भारत के प्रथम वायसराय बने।)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गवर्नर-जनरल / वायसराय एवं कार्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. लॉर्ड रिपन (1880-84)   |   1. बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\nB. लॉर्ड कर्जन (1899-1905)   |   2. व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\nC. लॉर्ड लिनलिथगो (1936-44)   |   3. स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\nD. लॉर्ड डलहौजी (1848-56)   |   4. प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"correct":0,"explanation":"सही सुमेलन: लॉर्ड रिपन (1880-84) (स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग), लॉर्ड कर्जन (1899-1905) (बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन), लॉर्ड लिनलिथगो (1936-44) (प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन), लॉर्ड डलहौजी (1848-56) (व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. भारत शासन अधिनियम, 1858   |   1. प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\nB. चार्टर अधिनियम, 1853   |   2. अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\nC. भारत शासन अधिनियम, 1935   |   3. कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\nD. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)   |   4. केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता","options":["A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: भारत शासन अधिनियम, 1858 (कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद), चार्टर अधिनियम, 1853 (केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता), भारत शासन अधिनियम, 1935 (अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण), भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) (प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग   |   1. बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\nB. स्वराज मेरा जन्मसिद्ध अधिकार है   |   2. महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\nC. ब्रिटिश साम्राज्य के ताबूत में कील   |   3. स्वामी दयानंद सरस्वती\nD. करो या मरो (Do or Die)   |   4. लाला लाजपत राय (साइमन कमीशन विरोध)","options":["A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2"],"correct":1,"explanation":"सही सुमेलन: वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग (स्वामी दयानंद सरस्वती), स्वराज मेरा जन्मसिद्ध अधिकार है (बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)), ब्रिटिश साम्राज्य के ताबूत में कील (लाला लाजपत राय (साइमन कमीशन विरोध)), करो या मरो (Do or Die) (महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942))।"},
  {"q":"'स्वराज मेरा जन्मसिद्ध अधिकार है और मैं इसे लेकर रहूँगा' — यह प्रसिद्ध नारा 1916 में किसने दिया?","options":["स्वामी दयानंद सरस्वती","पं. जवाहरलाल नेहरू","बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)","लाला लाजपत राय (साइमन कमीशन विरोध)"],"correct":2,"explanation":"बाल गंगाधर तिलक ने 1916 के लखनऊ कांग्रेस अधिवेशन और होमरूल अभियान में यह उद्घोष किया। तिलक ने 'गीता रहस्य', 'द आर्कटिक होम इन द वेदाज' व 'केसरी-मराठा' का भी संपादन किया।"},
  {"q":"किस वायसराय के कार्यकाल में 1940 का 'अगस्त प्रस्ताव' व 1942 का 'भारत छोड़ो आंदोलन' हुआ?","options":["प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन","बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना","सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)","द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त"],"correct":0,"explanation":"लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे। इन्हीं के काल में 1943 में बंगाल का भीषण अकाल पड़ा और सुभाषचंद्र बोस ने आजाद हिंद सरकार बनाई।"},
  {"q":"किस अधिनियम द्वारा 'बोर्ड ऑफ कंट्रोल' व 'कोर्ट ऑफ डायरेक्टर्स' समाप्त कर 'भारत राज्य सचिव' (Secretary of State) तथा 15-सदस्यीय परिषद बनी?","options":["भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष","कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद"],"correct":3,"explanation":"1858 के अधिनियम को शिक्षित भारतीयों ने 'अधिकारों का मैग्ना कार्टा' (महारानी विक्टोरिया घोषणा पत्र) कहा। लॉर्ड स्टेनली भारत के प्रथम भारत सचिव (Secretary of State for India) बने।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गवर्नर-जनरल / वायसराय एवं कार्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. लॉर्ड लिटन (1876-80)   |   1. द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\nB. चार्ल्स मेटकाफ (1835-36)   |   2. सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\nC. लॉर्ड विलियम बेंटिंक (1828-35)   |   3. वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\nD. वॉरेन हेस्टिंग्स (1772-85)   |   4. 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना","options":["A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: लॉर्ड लिटन (1876-80) (वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट), चार्ल्स मेटकाफ (1835-36) (1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना), लॉर्ड विलियम बेंटिंक (1828-35) (सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)), वॉरेन हेस्टिंग्स (1772-85) (द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n2. भारत शासन अधिनियम, 1935 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\n3. भारतीय परिषद अधिनियम, 1892 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (1858 के अधिनियम को शिक्षित भारतीयों ने 'अधिकारों का मैग्ना कार्टा' (महारानी विक्टोरिया घोषणा पत्र) कहा।) युग्म 2 सही (321 अनुच्छेद व 10 अनुसूचियों वाले 1935 के अधिनियम ने भारतीय संविधान के संरचनात्मक भाग में सर्वाधिक योगदान दिया।) युग्म 3 सही (1892 के अधिनियम में 'निर्वाचन' शब्द नहीं था, किंतु जिला बोर्ड/विश्वविद्यालयों द्वारा परोक्ष चुनाव प्रणाली आरंभ हुई।)।"},
  {"q":"[PSC/CDS युग्म पहचान — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लॉर्ड रिपन (1880-84) : 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण\n2. लॉर्ड लिटन (1876-80) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\n3. लॉर्ड मेयो (1869-72) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\n4. वॉरेन हेस्टिंग्स (1772-85) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: अकाल के समय भव्य दिल्ली दरबार (1877) तथा भारतीय भाषाई समाचार-पत्रों पर सेंसरशिप लॉर्ड लिटन की देन थी। (अन्य सही युग्म: लॉर्ड रिपन (1880-84)→स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग, लॉर्ड मेयो (1869-72)→1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण, वॉरेन हेस्टिंग्स (1772-85)→द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : पं. जवाहरलाल नेहरू\n2. करो या मरो (Do or Die) : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\n3. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : राम प्रसाद बिस्मिल (काकोरी कांड)\n4. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग' का सही संबंध 'स्वामी दयानंद सरस्वती' से है (न कि 'पं. जवाहरलाल नेहरू' से)। स्वामी दयानंद सरस्वती (मूलशंकर) ने 1875 में आर्य समाज व 'सत्यार्थ प्रकाश' की रचना की।"},
  {"q":"'देसी रियासतों का एकीकरण: सरदार पटेल, प्रजामंडल व ऑपरेशन पोलो' के ऐतिहासिक संदर्भ में 'तीन जटिल रियासतें' निम्नलिखित में से क्या है?","options":["सेफ्टी वॉल्व सिद्धांत (लाला लाजपत राय ने 'यंग इंडिया' में चर्चा की); आधुनिक मत: 'तड़ित चालक' (Lightning Conductor — गोखले ने ह्यूम का उपयोग किया)","1924 बेलगाम (महात्मा गांधी — एकमात्र अध्यक्षता); 1929 लाहौर (जवाहरलाल नेहरू — 'पूर्ण स्वराज' प्रस्ताव, 26 जनवरी 1930 प्रथम स्वतंत्रता दिवस)","मद्रास महाजन सभा (1884 — वी. राघवाचारी, जी. सुब्रमण्यम अय्यर, पी. आनंद चारलु); बॉम्बे प्रेसीडेंसी एसोसिएशन (1885 — फिरोजशाह मेहता, के.टी. तैलंग, बदरुद्दीन तैयबजी)","जूनागढ़ (फरवरी 1948 जनमत संग्रह से); हैदराबाद (सितंबर 1948 'ऑपरेशन पोलो' पुलिस/सैन्य कार्रवाई); जम्मू-कश्मीर (26 अक्टूबर 1947 महाराजा हरि सिंह का विलय पत्र)"],"correct":3,"explanation":"पांडिचेरी, कराकल, माहे व यनम 1954 में फ्रांस से समझौते द्वारा भारत में जुड़े, जबकि गोवा, दमन व दीव 1961 में 'ऑपरेशन विजय' द्वारा पुर्तगालियों से मुक्त हुए।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1935 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\n2. भारत शासन अधिनियम, 1858 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n3. रेगुलेटिंग एक्ट, 1773 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (321 अनुच्छेद व 10 अनुसूचियों वाले 1935 के अधिनियम ने भारतीय संविधान के संरचनात्मक भाग में सर्वाधिक योगदान दिया।) युग्म 2 गलत (सही: भारत शासन अधिनियम, 1858 — कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद)। युग्म 3 गलत (सही: रेगुलेटिंग एक्ट, 1773 — गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. आराम हराम है / 'Who lives if India dies?' : पं. जवाहरलाल नेहरू\n2. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n3. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा : स्वामी दयानंद सरस्वती\n4. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : राम प्रसाद बिस्मिल (काकोरी कांड)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा' का सही संबंध 'नेताजी सुभाष चंद्र बोस' से है (न कि 'स्वामी दयानंद सरस्वती' से)। सुभाष चंद्र बोस ने आजाद हिंद फौज (INA) के पुनर्गठन के दौरान मलाया-बर्मा में यह प्रसिद्ध आह्वान किया।"},
  {"q":"किस अधिनियम ने प्रांतीय द्वैध शासन समाप्त कर 'प्रांतीय स्वायत्तता' दी, केंद्र में द्वैध शासन प्रस्तावित किया तथा संघीय न्यायालय (1937) बनाया?","options":["कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण","गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष"],"correct":1,"explanation":"321 अनुच्छेद व 10 अनुसूचियों वाले 1935 के अधिनियम ने भारतीय संविधान के संरचनात्मक भाग में सर्वाधिक योगदान दिया। जवाहरलाल नेहरू ने इसे 'अनेक ब्रेकों वाली किंतु इंजन रहित मशीन' और 'दासता का नया चार्टर' कहा।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. चार्टर अधिनियम, 1813 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n2. भारतीय परिषद अधिनियम, 1909 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\n3. भारत शासन अधिनियम, 1935 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\n4. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: 1919 के भारत शासन अधिनियम (मोंटफोर्ड सुधार) ने महिलाओं को मताधिकार व भारत हेतु उच्चायुक्त पद भी सृजित किया। (अन्य सही युग्म: चार्टर अधिनियम, 1813→भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष, भारतीय परिषद अधिनियम, 1909→मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य, भारत शासन अधिनियम, 1935→अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. ब्रिटिश साम्राज्य के ताबूत में कील   |   1. स्वामी दयानंद सरस्वती\nB. आराम हराम है / 'Who lives if India dies?'   |   2. लाला लाजपत राय (साइमन कमीशन विरोध)\nC. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग   |   3. बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\nD. स्वराज मेरा जन्मसिद्ध अधिकार है   |   4. पं. जवाहरलाल नेहरू","options":["A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"correct":2,"explanation":"सही सुमेलन: ब्रिटिश साम्राज्य के ताबूत में कील (लाला लाजपत राय (साइमन कमीशन विरोध)), आराम हराम है / 'Who lives if India dies?' (पं. जवाहरलाल नेहरू), वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग (स्वामी दयानंद सरस्वती), स्वराज मेरा जन्मसिद्ध अधिकार है (बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916))।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड लिनलिथगो (1936-44) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n2. लॉर्ड रिपन (1880-84) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\n3. लॉर्ड कर्जन (1899-1905) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: लॉर्ड लिनलिथगो (1936-44) — प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन)। युग्म 2 गलत (सही: लॉर्ड रिपन (1880-84) — स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग)। युग्म 3 गलत (सही: लॉर्ड कर्जन (1899-1905) — बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन)।"},
  {"q":"'भारत भारतीयों के लिए है' (India for Indians) व 'वेदों की ओर लौटो' किस समाज सुधारक के प्रसिद्ध उद्घोष थे?","options":["स्वामी दयानंद सरस्वती","पं. जवाहरलाल नेहरू","लाला लाजपत राय (साइमन कमीशन विरोध)","बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)"],"correct":0,"explanation":"स्वामी दयानंद सरस्वती (मूलशंकर) ने 1875 में आर्य समाज व 'सत्यार्थ प्रकाश' की रचना की। वेलेंटाइन शिरोल ने इन्हें व तिलक को अपनी पुस्तक में 'भारतीय अशांति' से जोड़ा।"},
  {"q":"1942 के भारत छोड़ो आंदोलन के दौरान 'करो या मरो' (Do or Die) का मंत्र किसने दिया था?","options":["पं. जवाहरलाल नेहरू","महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)","बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)","स्वामी दयानंद सरस्वती"],"correct":1,"explanation":"महात्मा गांधी ने 8 अगस्त 1942 को बंबई के ग्वालिया टैंक (अगस्त क्रांति मैदान) में 'करो या मरो' मंत्र दिया। जबकि 'भारत छोड़ो' (Quit India) का प्रसिद्ध वाक्यांश समाजवादी नेता यूसुफ मेहरअली ने गढ़ा था।"}
]);
